    if (avatarMode === 'walk' || avatarMode === 'dance' || avatarMode === 'crouch') {
      console.log('🎮 Playing custom animation:', avatarMode);
      isIdleCycleActiveRef.current = false;
      
      if (actionsRef.current[avatarMode]) {
        playAnimation(avatarMode, () => {
          console.log('✅ Custom animation finished');
          isIdleCycleActiveRef.current = true;
          playIdleCycle();
        });
      }
      return;
    }

    if (avatarMode === "talk") {
      console.log("🗣️ AI started speaking - starting talking cycle");
      isIdleCycleActiveRef.current = false;
      talkingIndexRef.current = 0;
      playTalkingCycle();
    } else {
      console.log("😌 AI stopped speaking");
    }
  }, [avatarMode, playIdleCycle, playTalkingCycle, playAnimation]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const clock = new THREE.Clock();
    const animate = () => {
      requestAnimationFrame(animate);
      mixerRef.current?.update(clock.getDelta());
    };
    const animationId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <group ref={group}>
      <primitive object={scene} scale={1.6} position={[0, -2.2, 0]} />
    </group>
  );
});

FemaleAvatar.displayName = 'FemaleAvatar';

