export const Avatar3D = ({ avatarMode, companionId, onIntroComplete }) => {
  const [isLoading, setIsLoading] = useState(true);

  const isFemale = companionId === "priya_biology";
  const avatarName = isFemale ? "Priya 👩‍🔬" : "Omkar 🧑‍💻";

  if (!companionId) return null;

  return (
    <div className="w-full h-full relative">
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center text-white text-xl z-10 bg-gradient-to-br from-purple-900 to-indigo-900">
          <div className="text-center">
            <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-white mx-auto mb-4"></div>
            <p className="font-bold">Loading {avatarName}...</p>
          </div>
        </div>
      )}

      <Canvas
        onCreated={() => setTimeout(() => setIsLoading(false), 2000)}
        camera={{ position: [0, 0, 4], fov: 45 }}
      >
        <ambientLight intensity={0.8} />
        <directionalLight position={[5, 5, 5]} intensity={1} />
        <directionalLight position={[-5, -5, -5]} intensity={0.3} />
        <spotLight position={[0, 10, 0]} intensity={0.5} angle={0.3} />

        {isFemale ? (
          <FemaleAvatar avatarMode={avatarMode} onIntroComplete={onIntroComplete} />
        ) : (
          <MaleAvatar avatarMode={avatarMode} onIntroComplete={onIntroComplete} />
        )}
      </Canvas>
    </div>
  );
};

